from src.nodes.base import BaseNode
from src.runtime.assets.semantic import (
    get_asset_catalog_sync, get_asset_knowledge_graph, get_asset_catalog,
)

class Hou_Mcp_Catalog_Sync(BaseNode):
    name = "hou_mcp_catalog_sync"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("action",       "string", widget_type="text", default="sync_new")
        self.add_input("query",        "string", widget_type="text")
        self.add_input("category",     "string", widget_type="text")
        self.add_input("limit",        "int",    widget_type="int", default=50)
        self.add_input("force_update", "bool",   widget_type="checkbox", default=False)
        self.add_input("known_ids",    "list")
        self.add_output("report",  "any")
        self.add_output("added",   "int")
        self.add_output("updated", "int")
        self.add_output("ok",      "bool")
        # [AUTO-GENERATED-PORTS-END]

    async def execute(self, inputs):
        action       = str(inputs.get("action") or "sync_new").strip().lower()
        query        = str(inputs.get("query") or "").strip()
        category     = str(inputs.get("category") or "").strip()
        limit        = int(inputs.get("limit") or 50)
        force_update = bool(inputs.get("force_update") or False)
        known_ids    = inputs.get("known_ids") or []
        try:
            sync = get_asset_catalog_sync()
            if action == "sync":
                report = sync.sync_catalog(query=query, category=category, limit=limit, force_update=force_update)
            elif action == "sync_new":
                report = sync.sync_new_assets(query=query, limit=limit)
            elif action == "refresh":
                report = sync.refresh_existing_assets(limit=limit)
            elif action == "cleanup":
                report = sync.remove_deleted_assets(list(known_ids) if isinstance(known_ids, list) else [])
            elif action == "report":
                info = sync.build_sync_report()
                return {"report": info, "added": 0, "updated": 0, "ok": True, "exec_out": True}
            elif action == "build_graph":
                entries = [e.to_dict() for e in get_asset_catalog().iter_all()]
                added = get_asset_knowledge_graph().build_graph(entries)
                return {"report": {"graph_relationships_added": added}, "added": added, "updated": 0, "ok": True, "exec_out": True}
            else:
                return {"report": {}, "added": 0, "updated": 0, "ok": False, "exec_out": True}
            return {
                "report":  report.to_dict(),
                "added":   report.added,
                "updated": report.updated,
                "ok":      report.ok,
                "exec_out": True,
            }
        except Exception as e:
            self.log_error(f"hou_mcp_catalog_sync failed: {e}")
            return {"report": {}, "added": 0, "updated": 0, "ok": False, "exec_out": True}

def register_node():
    return Hou_Mcp_Catalog_Sync
